const smokeTrail = (x: number, y: number, n: number, dx: number, dy: number, r0: number, col: string = SMOKE) => all(...range(n).map((i) => puff(f1(x + dx * i), f1(y + dy * i), f1(r0 + i * 1.6), col)));
