const drop = (x: number, y: number, s = 1, col: string = WATER2, sw = 1.2) => at(x, y, s, path('M0 -9 C4 -3 6 0 6 3 C6 7 3 9 0 9 C-3 9 -6 7 -6 3 C-6 0 -4 -3 0 -9 Z', col, C.ink, sw));
const toxDrop = (x: number, y: number, s = 1) => all(drop(x, y, s, TOX), circle(f1(x - 2 * s), f1(y + 2 * s), 1.4 * s, '#c58ae0', null));
/** A small lumpy molecule of a poison. */
const molecule = (x: number, y: number, s = 1, col: string = TOX) => at(x, y, s, line('M-8 4 L0 -2 L8 4 M0 -2 L0 -10', C.ink, 1.6), circle(-8, 4, 4, col, C.ink, 1.2), circle(8, 4, 4, col, C.ink, 1.2), circle(0, -10, 3.4, col, C.ink, 1.2), circle(0, -2, 5, col, C.ink, 1.3));

